const input = $json ?? {};
const deal = input.deal ?? input.transaction ?? input;
const readiness = input.transaction_readiness ?? deal.transaction_readiness ?? {};
const pkg = input.closing_package ?? {};
const requiredDocs = Array.isArray(pkg.required_documents)
  ? pkg.required_documents
  : (Array.isArray(readiness.required_documents) ? readiness.required_documents : []);
const suppliedDocs = Array.isArray(pkg.supplied_documents)
  ? pkg.supplied_documents
  : (Array.isArray(readiness.supplied_documents) ? readiness.supplied_documents : []);

const suppliedById = new Map(suppliedDocs.map(d => [String(d?.id ?? d?.name ?? ''), d]));
const missingDocs = requiredDocs.filter(d => {
  const key = String(d?.id ?? d?.name ?? '');
  const supplied = suppliedById.get(key);
  const status = String(supplied?.status ?? d?.status ?? '').toLowerCase();
  return !supplied || !['complete','completed','received','verified','approved'].includes(status);
});

const identityComplete = Boolean(deal.deal_id ?? deal.transaction_id) &&
  Boolean(deal.property_id) &&
  Boolean(deal.lead_id ?? deal.seller_id);
const executed = String(deal.execution_state ?? deal.agreement?.execution_state ?? '').toLowerCase() === 'executed';
const signedEvidence = Boolean(deal.signed_evidence ?? deal.agreement?.signed_evidence);
const agreementType = String(deal.agreement_type ?? deal.agreement?.type ?? '').toLowerCase();
const validAgreementType = ['assignment','novation','double_close'].includes(agreementType);
const agreedPrice = Number(deal.agreed_price ?? deal.purchase_price ?? deal.contract_price);
const effectiveMao = Number(deal.effective_mao ?? deal.mao ?? deal.underwriting?.effective_mao);
const priceWithinMao = Number.isFinite(agreedPrice) && Number.isFinite(effectiveMao) ? agreedPrice <= effectiveMao : false;
const closingDate = pkg.closing_date ?? readiness.closing_date ?? deal.closing_date ?? deal.critical_dates?.closing_date ?? null;
const closingDateValid = Boolean(closingDate && !Number.isNaN(new Date(closingDate).getTime()));
const blockers = [
  ...(Array.isArray(deal.blockers) ? deal.blockers : []),
  ...(Array.isArray(readiness.blockers) ? readiness.blockers : []),
  ...(Array.isArray(pkg.blockers) ? pkg.blockers : [])
].filter(Boolean);

const partyReady = (x) => Boolean(x?.ready ?? x?.confirmed ?? String(x?.status ?? '').toLowerCase() === 'ready');
const partiesReady = {
  title: partyReady(pkg.title ?? readiness.title ?? deal.title),
  attorney: partyReady(pkg.attorney ?? readiness.attorney ?? deal.attorney),
  funding: partyReady(pkg.funding ?? readiness.funding ?? deal.funding),
  buyer: partyReady(pkg.buyer ?? readiness.buyer ?? deal.buyer)
};

let status = 'package_incomplete';
let severity = 'high';
if (!identityComplete || !executed || !signedEvidence || !validAgreementType || !priceWithinMao) {
  status = 'blocked';
  severity = 'urgent';
} else if (missingDocs.length || blockers.length || !Object.values(partiesReady).every(Boolean) || !closingDateValid) {
  status = 'package_incomplete';
  severity = 'high';
} else {
  status = 'package_ready';
  severity = 'normal';
}

const routing = status === 'package_ready'
  ? {next_workflow:'WF-126',reason:'Closing package is complete and ready for final closing coordination.'}
  : status === 'package_incomplete'
    ? {next_workflow:'WF-155',reason:'Closing package gaps remain and require milestone coordination.'}
    : {next_workflow:'WF-126',reason:'Transaction is blocked and requires closing coordination/human escalation.'};

return [{
  json:{
    ...input,
    workflow_id:'WF-176',
    workflow_name:'Transaction Readiness Reconciliation → Closing Package Finalization Controller',
    decision:{status,severity},
    identity_complete:identityComplete,
    execution_state:deal.execution_state ?? deal.agreement?.execution_state ?? null,
    signed_evidence_present:signedEvidence,
    agreement_type:agreementType || null,
    valid_agreement_type:validAgreementType,
    agreed_price:Number.isFinite(agreedPrice) ? agreedPrice : null,
    effective_mao:Number.isFinite(effectiveMao) ? effectiveMao : null,
    price_within_mao:priceWithinMao,
    required_document_count:requiredDocs.length,
    supplied_document_count:suppliedDocs.length,
    missing_document_count:missingDocs.length,
    missing_documents:missingDocs.map(d=>({id:d?.id ?? null,name:d?.name ?? null,status:d?.status ?? null})),
    parties_ready:partiesReady,
    closing_date:closingDate,
    closing_date_valid:closingDateValid,
    blockers,
    closing_package_status:status,
    routing
  }
}];

const out = $json ?? {};
return [{
  json:{
    ...out,
    workflow_id:'WF-176',
    result:'closing_package_finalization_evaluated',
    next_workflow:out.routing?.next_workflow ?? 'WF-126'
  }
}];
